import type {IncomingMessage, ListConversationsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_LIST_LIMIT = 200;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = messageValidators[message.type];
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

const messageValidators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
  list_conversations: validateListConversationsMessage,
};

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  let before: SessionCursor | undefined;

  if (!isValidLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be between 1 and 200'};
  }

  if (message.before !== undefined) {
    const cursor = validateCursor(message.before, 'list_sessions', value => isValidDate(value));
    if (!cursor.valid) return cursor;
    before = {updatedAt: cursor.updatedAt as string | number, sessionId: cursor.sessionId};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(message.limit === undefined ? {} : {limit: message.limit as number}),
      ...(before === undefined ? {} : {before}),
    },
  };
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (!isValidLimit(message.limit)) {
    return {valid: false, error: 'list_conversations limit must be between 1 and 200'};
  }

  let before: ListConversationsMessage['before'];
  if (message.before !== undefined) {
    const cursor = validateCursor(
      message.before,
      'list_conversations',
      value => typeof value === 'string' && isValidDate(value)
    );
    if (!cursor.valid) return cursor;
    before = {updatedAt: cursor.updatedAt as string, sessionId: cursor.sessionId};
  }

  return {
    valid: true,
    data: {
      type: 'list_conversations',
      ...(message.limit === undefined ? {} : {limit: message.limit as number}),
      ...(before === undefined ? {} : {before}),
    },
  };
}

function isValidLimit(value: unknown): value is number | undefined {
  if (value === undefined) return true;
  return Number.isInteger(value) && isWithinLimit(value as number);
}

function isWithinLimit(value: number): boolean {
  return value >= 1 && value <= MAX_LIST_LIMIT;
}

function validateCursor(
  value: unknown,
  type: string,
  validDate: (value: unknown) => boolean
): {valid: true; updatedAt: string | number; sessionId: string} | ValidationFailure {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return {valid: false, error: `${type} before must be a cursor object`};
  }
  const cursor = value as Record<string, unknown>;
  if (typeof cursor.sessionId !== 'string' || cursor.sessionId.length < 1 || cursor.sessionId.length > 128) {
    return {valid: false, error: `${type} before.sessionId must be 1-128 characters`};
  }
  if (!validDate(cursor.updatedAt)) {
    return {valid: false, error: `${type} before.updatedAt must be a valid date`};
  }
  return {valid: true, updatedAt: cursor.updatedAt as string | number, sessionId: cursor.sessionId};
}

function isValidDate(value: unknown): boolean {
  if (typeof value === 'string') return Number.isFinite(Date.parse(value));
  if (typeof value === 'number') return Number.isFinite(value) && Number.isFinite(new Date(value).getTime());
  return false;
}
